impl sts2_core::PowerTable for Power {
    /// Whether a negative amount means one endless instance.
    ///
    /// True for the powers whose stacking is `dynamic` in
    /// the dump. A power that works its stack type out at
    /// the time works it out from the amount, and below
    /// zero it is one instance rather than a counter.
    fn endless_below_zero(self) -> bool {
        matches!(
            <Self as sts2_core::Table>::data(self).stack,
            Field::Computed
        )
    }

    /// Whether the game counts this as a debuff.
    ///
    /// `None` for the powers whose type is `dynamic` in the dump:
    /// they decide at the time, and a caller wanting the answer for
    /// an amount has to ask the creature.
    fn debuff(self) -> Option<bool> {
        match <Self as sts2_core::Table>::data(self).kind {
            Field::Constant(PowerType::Debuff) => Some(true),
            Field::Constant(PowerType::Buff) => Some(false),
            Field::Computed => None,
        }
    }

    fn overrides(self) -> sts2_core::Overrides {
        OVERRIDES[self as usize]
    }

    fn instanced(self) -> bool {
        <Self as sts2_core::Table>::data(self).instance.is_some()
    }

    fn per_applier(self) -> bool {
        matches!(
            <Self as sts2_core::Table>::data(self).instance,
            Some(PowerInstanceType::InstancedPerApplier)
        )
    }

    fn overrides_virtual(self, method: sts2_core::PowerVirtual) -> bool {
        let bit = match method {
            sts2_core::PowerVirtual::BeforeApplied => 1,
            sts2_core::PowerVirtual::AfterApplied => 2,
            sts2_core::PowerVirtual::AfterRemoved => 4,
        };
        VIRTUALS[self as usize] & bit != 0
    }
}

